mapper.select:
SELECT ar.*, an.node_name, u.real_name AS approver_name, u.role AS approver_role FROM approval_record ar LEFT JOIN approval_node an ON ar.node_id = an.id LEFT JOIN sys_user u ON ar.approver_id = u.id WHERE 1 = 1
AND ar.subject_type = #{subjectType}
AND ar.subject_id = #{subjectId}
AND ar.action = #{action}
ORDER BY ar.create_time DESC
